                        { id: 'reg_notif',  labelKey: 'reg_notif_lbl',  options: [{v:2,k:'rn2'},{v:1,k:'rn1'},{v:0,k:'rn0'}] },
                        { id: 'statement',  labelKey: 'statement_lbl',  options: [{v:2,k:'st2'},{v:0,k:'st0'},{v:1,k:'st1'}] },
                        { id: 'law_enf',    labelKey: 'law_enf_lbl',    options: [{v:0,k:'le0'},{v:1,k:'le1'},{v:2,k:'le2'}] }
                    ]
                },
                {
