                    timeLabel: '10:00 a.m.',
                    briefingKey: 'r3_briefing',
                    events: [
                        { key: 'r3_ev1', ces: -10, cti:   0, rrs:  0 },
                        { key: 'r3_ev2', ces:   0, cti:  +3, rrs:  0 },
                        { key: 'r3_ev3', ces:   0, cti:  -8, rrs:  0 }
                    ],
                    decisions: [
                        { id: 'eradication', labelKey: 'eradication_lbl', options: [{v:0,k:'er0'},{v:1,k:'er1'},{v:2,k:'er2'}] },
                        { id: 'cust_notif',  labelKey: 'cust_notif_lbl',  options: [{v:2,k:'cn2'},{v:1,k:'cn1'},{v:0,k:'cn0'}] },
                        { id: 'ceo_vis',     labelKey: 'ceo_vis_lbl',     options: [{v:2,k:'cv2'},{v:0,k:'cv0'},{v:1,k:'cv1'}] },
                        { id: 'social_r3',   labelKey: 'social_r3_lbl',   options: [{v:1,k:'sr3_1'},{v:2,k:'sr3_2'},{v:0,k:'sr3_0'}] }
                    ]
