                    ],
                    decisions: [
                        { id: 'recovery',    labelKey: 'recovery_lbl',    options: [{v:2,k:'rec2'},{v:0,k:'rec0'},{v:1,k:'rec1'}] },
                        { id: 'budget',      labelKey: 'budget_lbl',      options: [{v:0,k:'bud0'},{v:1,k:'bud1'},{v:2,k:'bud2'}] },
                        { id: 'cust_assur',  labelKey: 'cust_assur_lbl',  options: [{v:2,k:'ca2'},{v:0,k:'ca0'},{v:1,k:'ca1'}] },
                        { id: 'board_comms', labelKey: 'board_comms_lbl', options: [{v:0,k:'bc0'},{v:1,k:'bc1'},{v:2,k:'bc2'}] }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                var evts = this.ROUNDS.map(function(r) {
                    return Math.floor(Math.random() * r.events.length);
                });
                state.domainState = {
                    ces: 0,
                    cti: 72,
                    rrs: 35,
                    fis: 0,
                    projDays: 19,
                    ransomPaid: false,
                    lawEnfLevel: -1,
                    irCost: 0.18,
                    remBudget: 0,
                    selectedEvents: evts,
                    roundDecs: {},
                    cesHistory: [],
                    ctiHistory: [],
                    rrsHistory: [],
                    fisHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 80);
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var ds = state.domainState || {};

            var phaseEl = document.getElementById('roundPhaseDisplay');
            if (phaseEl) phaseEl.textContent = window.mySimulation.t(round.titleKey);

            var timeEl = document.getElementById('roundTimeDisplay');
            if (timeEl) timeEl.textContent = round.timeLabel;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation.t(round.briefingKey);

            var evtIdx = (ds.selectedEvents && ds.selectedEvents[idx] !== undefined) ? ds.selectedEvents[idx] : 0;
            var evtPanel = document.getElementById('eventPanel');
            var evtText  = document.getElementById('eventText');
            if (evtPanel && evtText) {
                evtText.innerHTML = window.mySimulation.t(round.events[evtIdx].key);
                evtPanel.style.display = 'block';
            }

            var decPanel = document.getElementById('decisionsPanel');
            if (!decPanel) return;
            var html = '';
            var savedDecs = ds.roundDecs || {};
            round.decisions.forEach(function(dec) {
                html += '<div class="cvfg-decision-group">';
                html += '<div class="cvfg-decision-label">' + window.mySimulation.t(dec.labelKey) + '</div>';
                html += '<div class="cvfg-decision-options">';
                dec.options.forEach(function(opt) {
                    var savedVal = (savedDecs[dec.id] !== undefined) ? savedDecs[dec.id] : -1;
                    var checked  = (savedVal === opt.v) ? 'checked' : '';
                    var selClass = (savedVal === opt.v) ? ' selected' : '';
                    html += '<label class="cvfg-option-label' + selClass + '">';
                    html += '<input type="radio" name="dec_' + dec.id + '" value="' + opt.v + '" ' + checked + ' onchange="window.cvfgOnChange()">';
                    html += '<span class="cvfg-option-text">' + window.mySimulation.t(opt.k) + '</span>';
                    html += '</label>';
                });
                html += '</div></div>';
            });
            decPanel.innerHTML = html;
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            // NOTE: do NOT call _updateBriefing here — it would wipe the user's radio selections

            var period = state.currentPeriod || 1;
            var idx    = Math.min(period - 1, this.ROUNDS.length - 1);
            var round  = this.ROUNDS[idx];
            var allOk  = true;

            round.decisions.forEach(function(dec) {
                var checked = document.querySelector('input[name="dec_' + dec.id + '"]:checked');
                if (!checked) { allOk = false; }
            });

            if (!allOk) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('all_required'), 'warning'
                );
                return false;
            }

            round.decisions.forEach(function(dec) {
                var checked = document.querySelector('input[name="dec_' + dec.id + '"]:checked');
                if (checked) decisions[dec.id] = parseInt(checked.value);
            });
            return true;
        }

        calculateResults(state) {
            var d   = state.decisions;
            var ds  = state.domainState;
            var per = state.currentPeriod;
            var idx = Math.min(per - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            if (!ds.roundDecs) ds.roundDecs = {};
            round.decisions.forEach(function(dec) {
                if (d[dec.id] !== undefined) ds.roundDecs[dec.id] = d[dec.id];
            });

            var evtIdx = (ds.selectedEvents && ds.selectedEvents[idx] !== undefined) ? ds.selectedEvents[idx] : 0;
            var evt = round.events[evtIdx];
            ds.ces = Math.max(0, Math.min(100, ds.ces + (evt.ces || 0)));
            ds.cti = Math.max(0, Math.min(100, ds.cti + (evt.cti || 0)));
            ds.rrs = Math.max(0, Math.min(100, ds.rrs + (evt.rrs || 0)));

            if (per === 1) {
                var cesByIR  = [18, 10, 3];
                var cesByGW  = [17, 10, 3];
                ds.ces += (cesByIR[d.ir_vendor]   || 3) + (cesByGW[d.gateway_iso] || 3);
                ds.ces = Math.min(100, ds.ces);
                ds.irCost = [0.18, 0.35, 0.8][d.ir_vendor] || 0.8;
                if (d.gateway_iso === 2) ds.projDays += 4;
                var ctiSoc = [5, 0, -8];
                ds.cti = Math.max(0, Math.min(100, ds.cti + (ctiSoc[d.social_r1] || 0)));
                ds.fis = 0.5 + ds.irCost;
                // v1.2.0: incident command is scored (it was read by nothing before). A formal ICS convenes the
                // technical, legal, communications and executive teams under one commander and costs nothing.
                // Ad hoc coordination loses containment time, sends mixed messages and lets notifications slip.
                // Delegating fully to the CISO keeps the technical work moving but leaves customer messaging and
                // the regulatory clock without an executive owner.
                var cmdIdx = (d.incid_cmd === 1 || d.incid_cmd === 2) ? d.incid_cmd : 0;
                ds.ces = Math.max(0, Math.min(100, ds.ces + [0, -5, -2][cmdIdx]));
                ds.cti = Math.max(0, Math.min(100, ds.cti + [0, -4, -6][cmdIdx]));
                ds.rrs = Math.max(0, Math.min(100, ds.rrs + [0, 6, 10][cmdIdx]));
            }

            if (per === 2) {
                var rrsByNotif = [0, 8, 18];
                var rrsByLaw   = [-10, 0, 15];
                ds.rrs = Math.max(0, Math.min(100,
                    ds.rrs + (rrsByNotif[d.reg_notif] || 0) + (rrsByLaw[d.law_enf] || 0)
                ));
                ds.lawEnfLevel = d.law_enf;
                if (d.ransom === 0) {
                    ds.ransomPaid = true;
                    ds.rrs = Math.max(0, Math.min(100, ds.rrs + 15));
                    ds.projDays = 3;
                } else if (d.ransom === 2) {
                    ds.rrs = Math.max(0, Math.min(100, ds.rrs + 5));
                    ds.projDays = Math.round(ds.projDays * 0.9);
                } else if (d.ransom === 3) {
                    ds.rrs = Math.max(0, Math.min(100, ds.rrs + 8));
                    ds.projDays += 2;
                }
                var ctiSt  = [10, 0, -12];
                var ctiRan = [0, 2, 0, -5];
                ds.cti = Math.max(0, Math.min(100,
                    ds.cti + (ctiSt[d.statement] || 0) + (ctiRan[d.ransom] || 0)
                ));
                ds.fis += 0.5 + (ds.ransomPaid ? 4.2 : 0);
            }

            if (per === 3) {
                var cesByEr = [25, 20, 12];
                ds.ces = Math.min(100, ds.ces + (cesByEr[d.eradication] || 12));
                if (d.eradication === 2) ds.projDays += 7;
                var ctiByCEO  = [7, 3, -5];
                var ctiByCN   = [12, 4, -3];
                var ctiBySoc3 = [5, 0, -8];
                ds.cti = Math.max(0, Math.min(100,
                    ds.cti + (ctiByCEO[d.ceo_vis] || 0) + (ctiByCN[d.cust_notif] || 0) + (ctiBySoc3[d.social_r3] || 0)
                ));
                var rrsByCN = [-5, 0, 8];
                ds.rrs = Math.max(0, Math.min(100, ds.rrs + (rrsByCN[d.cust_notif] || 0)));
                var rf = ds.rrs < 40 ? 2.0 : ds.rrs < 55 ? 5.0 : ds.rrs < 70 ? 9.0 : 16.0;
                ds.fis += 0.5 + rf;
            }

            if (per === 4) {
                var cesByRec = [12, 15, 18];
                var cesByBud = [5,  12, 22];
                ds.ces = Math.min(100, ds.ces + (cesByRec[d.recovery] || 12) + (cesByBud[d.budget] || 5));
                if (d.recovery === 1 && ds.ransomPaid) ds.projDays = 3;
                else if (d.recovery === 2) ds.projDays = Math.round(ds.projDays * 0.6);
                var ctiByCAs = [5, 2, -3];
                var ctiByBCs = [3, 0, -5];
                ds.cti = Math.max(0, Math.min(100,
                    ds.cti + (ctiByCAs[d.cust_assur] || 0) + (ctiByBCs[d.board_comms] || 0)
                ));
                var rrsByBC = [-5, 0, 8];
                ds.rrs = Math.max(0, Math.min(100, ds.rrs + (rrsByBC[d.board_comms] || 0)));
                ds.remBudget = [2.0, 4.5, 8.0][d.budget] || 2.0;
                var opLoss   = ds.projDays * 0.5;
                var ranCost  = ds.ransomPaid ? 4.2 : 0;
                var ofac     = (ds.ransomPaid && ds.lawEnfLevel === 2) ? 2.1 : 0;
                var regFine2 = ds.rrs < 40 ? 2.0 : ds.rrs < 55 ? 5.0 : ds.rrs < 70 ? 9.0 : 16.0;
                var gross    = opLoss + ranCost + ofac + regFine2 + ds.irCost + ds.remBudget;
                var insure   = Math.min(Math.max(0, gross - ds.remBudget - 0.5), 9.5);
                ds.fis       = Math.max(0, gross - insure);
                var compScore  = Math.max(0, 100 - ds.rrs);
                var maxFIS     = 50;
                var fisScore   = Math.max(0, 100 - (ds.fis / maxFIS * 100));
                ds.oos = Math.round((ds.ces + ds.cti + compScore + fisScore) / 4);
            }

            ds.cesHistory.push(Math.round(ds.ces));
            ds.ctiHistory.push(Math.round(ds.cti));
            ds.rrsHistory.push(Math.round(ds.rrs));
            ds.fisHistory.push(Math.round(ds.fis * 10) / 10);
            // --- v1.1.0 fix: persist gradebook composite (OOS) every period ---
            var _fisScoreP = Math.max(0, 100 - (ds.fis / 50 * 100));
            var _compScoreP = Math.max(0, 100 - ds.rrs);
            var _oosLive = (typeof ds.oos === 'number') ? ds.oos : Math.round((ds.ces + ds.cti + _compScoreP + _fisScoreP) / 4);
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _oosLive;
            ds.performance.score = _oosLive;

            var self = this;
            var nextPer = per + 1;
            if (per < 4) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPer, domainState: ds });
                }, 500);
            }

            return {
                period:      per,
                overallScore: _oosLive,
                score:       _oosLive,
                ces:         Math.round(ds.ces),
                cti:         Math.round(ds.cti),
                rrs:         Math.round(ds.rrs),
                fis:         Math.round(ds.fis * 10) / 10,
                oos:         ds.oos || null,
                recovDays:   ds.projDays,
                ransomPaid:  ds.ransomPaid
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay',  'currentPeriod');
            uiManager.bind('maxPeriods',  'maxPeriods');
            uiManager.bind('cesDisplay',  'domainState.ces',  function(v) { return Math.round(v); });
            uiManager.bind('ctiDisplay',  'domainState.cti',  function(v) { return Math.round(v); });
            uiManager.bind('rrsDisplay',  'domainState.rrs',  function(v) { return Math.round(v); });
            uiManager.bind('fisDisplay',  'domainState.fis',  function(v) { return 'AV$' + (Math.round(v * 10) / 10).toFixed(1) + 'M'; });
        }

