                            { label: 'CTI — Customer Trust',  data: [], borderColor: '#2e7d32', backgroundColor: 'rgba(46,125,50,0.08)',   borderWidth: 3, fill: false, tension: 0.3, pointBackgroundColor: '#2e7d32' },
                            { label: 'RRS — Regulatory Risk', data: [], borderColor: '#c62828', backgroundColor: 'rgba(198,40,40,0.08)',   borderWidth: 3, fill: false, tension: 0.3, pointBackgroundColor: '#c62828' }
                        ]
                    },
