        getChartData(state) {
            var ds  = state.domainState;
            var lbs = ds.cesHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                kpiChart:      { labels: lbs, datasets: [{ data: ds.cesHistory }, { data: ds.ctiHistory }, { data: ds.rrsHistory }] },
                financialChart:{ labels: lbs, datasets: [{ data: ds.fisHistory }] }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds   = (last && last.domainState) ? last.domainState : {};
            var oos  = ds.oos || 0;
            var perf, grade, _tier;
            if (oos >= 85)      { perf = 'Exemplary Response';  grade = 'success'; _tier = 'exemplary'; }
            else if (oos >= 70) { perf = 'Competent Response';  grade = 'info';    _tier = 'competent'; }
            else if (oos >= 55) { perf = 'Stressed Response';   grade = 'warning'; _tier = 'stressed';  }
            else                { perf = 'Crisis Failure';      grade = 'danger';  _tier = 'failure';   }
            var _tt = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var performanceLabel = _tt('grade_' + _tier);

            var insights = [];
            insights.push(((ds.ces || 0) >= 75) ? _tt('insight_ces_good') : _tt('insight_ces_bad'));
            insights.push(((ds.cti || 72) >= 65) ? _tt('insight_cti_good') : _tt('insight_cti_bad'));
            insights.push(((ds.rrs || 35) <= 50) ? _tt('insight_rrs_good') : _tt('insight_rrs_bad'));
            if ((ds.fis || 0) <= 15) insights.push(_tt('insight_fis_good'));
            else insights.push(_tt('insight_fis_bad').replace('@FIS@', (ds.fis || 0).toFixed(1)));
            insights.push(ds.ransomPaid ? _tt('insight_ransom_paid') : _tt('insight_ransom_refused'));
            if (ds.roundDecs && ds.roundDecs.incid_cmd !== undefined) {
                insights.push(ds.roundDecs.incid_cmd === 0 ? _tt('insight_cmd_good') : _tt('insight_cmd_bad'));
            }
            return { oos: oos, overallScore: oos, score: oos, ces: ds.ces || 0, cti: ds.cti || 72, rrs: ds.rrs || 35, fis: ds.fis || 0, performance: perf, performanceLabel: performanceLabel, grade: grade, tier: _tier, insights: insights };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.period === 1 && results.ces < 20) return window.mySimulation.t('hint_ces_r1');
            if (results.period === 1 && ((state.domainState || {}).roundDecs || {}).incid_cmd > 0) return window.mySimulation.t('hint_cmd_r1');
            if (results.period === 1 && results.cti < 67) return window.mySimulation.t('hint_cti_r1');
            if (results.period === 2 && results.rrs > 60) return window.mySimulation.t('hint_rrs_r2');
            if (results.period === 3 && results.cti < 50) return window.mySimulation.t('hint_cti_r3');
            if (results.period === 4 && results.oos !== null && results.oos < 55) return window.mySimulation.t('hint_oos_low');
            return null;
        }

