            return [
                { key: 'results.period', label: 'Round',         i18nKey: 'col_round' },
                { key: 'results.ces',    label: 'CES',           i18nKey: 'col_ces'   },
                { key: 'results.cti',    label: 'CTI',           i18nKey: 'col_cti'   },
                { key: 'results.rrs',    label: 'RRS',           i18nKey: 'col_rrs'   },
                { key: 'results.fis',    label: 'FIS (AV$M)',    i18nKey: 'col_fis',
                  formatter: function(v) { return 'AV$' + v + 'M'; } }
            ];
        }

        getPresets() { return null; }

        _t(key) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return null;
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            function L(k, f) { var v = self._t(k); return v || f; }
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore
                      : (typeof summary.oos === 'number' ? summary.oos : 0);
            var verdict = summary.performanceLabel || summary.performance || '';
            var met = score >= 70;
            var badge = met ? L('cm_pass', 'Target met') : L('cm_below', 'Below target');
            var badgeClass = met ? 'cyber-cm-pass' : 'cyber-cm-below';
            var kpiDefs = [['CES', summary.ces, 'cm_kpi_ces'], ['CTI', summary.cti, 'cm_kpi_cti'], ['RRS', summary.rrs, 'cm_kpi_rrs']];
            var kpis = '';
            for (var j = 0; j < kpiDefs.length; j++) {
                kpis += '<div class="cyber-cm-kpi"><span class="cyber-cm-kpi-v">' + Math.round(kpiDefs[j][1] || 0) + '</span><span class="cyber-cm-kpi-l">' + L(kpiDefs[j][2], kpiDefs[j][0]) + '</span></div>';
            }
            kpis += '<div class="cyber-cm-kpi"><span class="cyber-cm-kpi-v">AV$' + ((summary.fis || 0).toFixed(1)) + 'M</span><span class="cyber-cm-kpi-l">' + L('cm_kpi_fis', 'Financial impact') + '</span></div>';
            var insights = summary.insights || [];
            var insHtml = '';
            if (insights.length) { insHtml = '<ul class="cyber-cm-insights">'; for (var i = 0; i < insights.length; i++) { insHtml += '<li>' + insights[i] + '</li>'; } insHtml += '</ul>'; }
            return '' +
                '<div class="cyber-cm">' +
